k = input(7, "K Neighbors", 1, 20, 1)
featureBars = input(20, "Feature Bars", 5, 40, 1)
searchback = input(200, "Searchback", 30, 500, 10)
marginThresh = input(0.4286, "Margin Threshold", 0.1, 1.0, 0.01)
disagreeThresh = input(0.5, "Disagree Threshold", 0.05, 1.0, 0.05)
showLabels = input(true, "Show Labels")

varip retHist = array(0)
varip closeHist = array(0)
var lastState = 0

ret = 0.0
if bar_index > 0 {
    denom = close[1] + 0.000000001
    ret := (close - close[1]) / denom
}

array.push(retHist, ret)
array.push(closeHist, close)

numBars = array.size(retHist)
curIdx = numBars - 1

margin = 0.0
disn = 1.0
bullVotes = 0
bearVotes = 0
meanD = 0.0

if numBars > featureBars + 1 {
    searchStart = curIdx - searchback
    if searchStart < featureBars {
        searchStart := featureBars
    }
    searchEnd = curIdx - 1

    bestDist = array()
    bestTarg = array()
    b = 0
    while b < k {
        array.push(bestDist, 999999.0)
        array.push(bestTarg, 0)
        b := b + 1
    }

    j = searchStart
    while j <= searchEnd {
        dsum = 0.0
        f = 0
        while f < featureBars {
            a = retHist[curIdx - featureBars + 1 + f]
            c = retHist[j - featureBars + 1 + f]
            diff = a - c
            dsum := dsum + diff * diff
            f := f + 1
        }
        dist = sqrt(dsum)
        lab = 0 - 1
        if closeHist[j + 1] > closeHist[j] {
            lab := 1
        }
        insIdx = 0 - 1
        m = 0
        while m < k {
            if dist < bestDist[m] {
                insIdx := m
                m := k
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = k - 1
            while m > insIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestTarg, m, bestTarg[m - 1])
                m := m - 1
            }
            array.set(bestDist, insIdx, dist)
            array.set(bestTarg, insIdx, lab)
        }
        j := j + 1
    }

    bv = 0
    q = 0
    while q < k {
        if bestDist[q] < 999999.0 {
            if bestTarg[q] == 1 {
                bv := bv + 1
            }
        }
        q := q + 1
    }
    bullVotes := bv
    bearVotes := k - bv
    margin := (bullVotes - bearVotes) / k

    s = 0.0
    q = 0
    while q < k {
        s := s + bestDist[q]
        q := q + 1
    }
    meanD := s / k
    vsum = 0.0
    q = 0
    while q < k {
        dd = bestDist[q] - meanD
        vsum := vsum + dd * dd
        q := q + 1
    }
    sdD = sqrt(vsum / k)
    dis = sdD / (meanD + 0.000000001)
    capped = dis
    if capped > 1.5 {
        capped := 1.5
    }
    disn := capped / 1.5
}

bullCrisp = margin >= marginThresh and disn <= disagreeThresh
bearCrisp = margin <= (0 - marginThresh) and disn <= disagreeThresh
buySig = bullCrisp and lastState != 1
sellSig = bearCrisp and lastState != (0 - 1)

if showLabels {
    if buySig {
        plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    }
    if sellSig {
        plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    }
}

curState = 0
if bullCrisp {
    curState := 1
}
if bearCrisp {
    curState := 0 - 1
}
if curState != 0 {
    lastState := curState
}
if curState == 0 {
    if bullCrisp == false and bearCrisp == false {
        lastState := 0
    }
}

marginLine = margin
disLine = disn
marginPillar = margin * 100
disagreePillar = disn * 100

plot(marginLine, "Vote Margin M", "#22cc88", 2, "line", "separate")
plot(disLine, "Disagreement DISn", "#ff9f43", 2, "line", "separate")
hline(0.4286, "#22cc88", "separate")
hline(-0.4286, "#ff4477", "separate")
hline(0.5, "#ff9f43", "separate")

plot3d(marginPillar, "Vote Margin Pillars", "bars3d", "#22cc88", "separate")
plot3d(disagreePillar, "Disagreement Depth", "ribbon", "#ff9f43", "separate", 1)

// Visible Session Volume Value Model
// Session volume profile: POC + value area expansion, breakout signals on leaving value.

rows = input(24, "Rows", 10, 48, 1)
vaPct = input(70, "ValueAreaPercent", 50, 90, 5)
lookback = input(120, "SessionLookbackBars", 40, 300, 10)
showVA = input(true, "ShowValueArea")
showRail = input(true, "ShowPOCRail")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range ───────────────────────────────────────────────
hh = highest(high, lookback)
ll = lowest(low, lookback)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
binH = rng / rows

// ─── Build volume-at-price bins over session window ──────────────
binVol = array()
i = 0
while i < rows {
    array.push(binVol, 0.0)
    i := i + 1
}
totalVol = 0.0
j = 0
while j < lookback {
    typ = (high[j] + low[j] + close[j]) / 3
    vv = volume[j]
    totalVol := totalVol + vv
    b = floor((typ - ll) / rng * rows)
    if b < 0 {
        b := 0
    }
    if b > rows - 1 {
        b := rows - 1
    }
    array.set(binVol, b, array.get(binVol, b) + vv)
    j := j + 1
}
if totalVol <= 0 {
    totalVol := 1.0
}

// ─── POC: bin with maximum volume ────────────────────────────────
pocBin = 0
pocVol = array.get(binVol, 0)
i = 1
while i < rows {
    v = array.get(binVol, i)
    if v > pocVol {
        pocVol := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) * binH

// ─── Value area: expand from POC adding higher-volume neighbor ───
vaLow = pocBin
vaHigh = pocBin
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < rows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) * binH
valPrice = ll + vaLow * binH
pocShare = pocVol / totalVol * 100
vaShare = accum / totalVol * 100

// ─── Signal state: close vs value ────────────────────────────────
inside = close >= valPrice and close <= vahPrice
inside1 = close[1] >= valPrice[1] and close[1] <= vahPrice[1]
inside2 = close[2] >= valPrice[2] and close[2] <= vahPrice[2]
buySig = close > vahPrice and inside1 and inside2
sellSig = close < valPrice and inside1 and inside2

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    model.longEntry("VPBreakUp")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    model.shortEntry("VPBreakDn")
}

// ─── 3D signal cones in main scene ───────────────────────────────
sigSpread = (vahPrice - valPrice) / rng * 2.0 + 0.6
if sigSpread < 0.6 {
    sigSpread := 0.6
}
if sigSpread > 2.2 {
    sigSpread := 2.2
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", sigSpread * markerSize, 1, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", sigSpread * markerSize, 1, "3d")
}
if showRail {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}

// ─── 2D: identical POC/VAH/VAL info when 3D is off ───────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(close, "Close", "#ffffff", 1)
if inside {
    bgcolor("rgba(68,136,255,0.06)")
} else {
    bgcolor("rgba(255,136,0,0.06)")
}

// ─── 2D volume-profile histogram on right edge (price bins) ──────
k = 0
while k < rows {
    bv = array.get(binVol, k)
    wBars = bv / totalVol * 30
    binTop = ll + (k + 1) * binH
    binBot = ll + k * binH
    isVA = k >= vaLow and k <= vaHigh
    isPOC = k == pocBin
    bc = "rgba(100,120,160,0.55)"
    if isVA {
        bc := "rgba(68,136,255,0.70)"
    }
    if isPOC {
        bc := "rgba(255,212,59,0.90)"
    }
    box.new(bar_index + 1, binTop, bar_index + 1 + wBars, binBot, bc, bc, 1)
    k := k + 1
}

// ─── 3D: value terrain + POC rail + value boundary rails ─────────
terrainCol = "#4488ff"
if not inside {
    terrainCol := "#ff8800"
}
plot3d(close, "Value Terrain", "surface", terrainCol, "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)

